const $ = (s) => document.querySelector(s);
const icon = (name, cls='') => `<svg class="${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DEMO = {title:'A little moment in bloom · คลิปตัวอย่าง',source:'demo',url:'/assets/flower.mp4',thumbnail:'/assets/flower.jpg',format:'mp4',quality:'ต้นฉบับ',duration:5};
let platform='all',format='mp4',busy=false,apiKey='',apiBase='https://clipkeep-api.onrender.com',records=[],rememberKey=false;
try{apiBase=localStorage.getItem('clipkeep-api')??'https://clipkeep-api.onrender.com';records=JSON.parse(localStorage.getItem('clipkeep-history')||'[]');if(!Array.isArray(records))records=[];records=records.filter(r=>r&&typeof r.url==='string'&&typeof r.title==='string'&&(r.source==='demo'||parseLink(r.url)));}catch{records=[];}
function storedConnection(storage){try{const saved=JSON.parse(storage.getItem('clipkeep-connection')||'null');return saved&&saved.base===apiBase&&typeof saved.key==='string'&&saved.key?saved:null;}catch{return null;}}
try{const saved=storedConnection(localStorage);if(saved){apiKey=saved.key;rememberKey=true;}}catch{}
if(!apiKey){try{apiKey=storedConnection(sessionStorage)?.key||'';}catch{}}
function saveConnectionKey(remember){const value=JSON.stringify({base:apiBase,key:apiKey});try{sessionStorage.setItem('clipkeep-connection',value);}catch{}rememberKey=false;try{if(remember){localStorage.setItem('clipkeep-connection',value);rememberKey=true;}else localStorage.removeItem('clipkeep-connection');return true;}catch{return !remember;}}
function parseLink(value){try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol)||u.username||u.password||u.port)return null;const host=u.hostname.toLowerCase();if(['youtube.com','www.youtube.com','m.youtube.com','music.youtube.com','youtu.be'].includes(host)){const id=host==='youtu.be'?u.pathname.split('/')[1]:u.pathname==='/watch'?u.searchParams.get('v'):u.pathname.match(/^\/(?:shorts|live|embed)\/([^/]+)/)?.[1];if(!/^[a-zA-Z0-9_-]{11}$/.test(id||''))return null;return {source:'youtube',id,url:`https://www.youtube.com/watch?v=${id}`};}if(['facebook.com','www.facebook.com','m.facebook.com','web.facebook.com','fb.watch'].includes(host)){if(host==='fb.watch'&&u.pathname.length>2||/^\/(?:reel|share\/(?:v|r))\/.+/.test(u.pathname)||/\/videos\/.+/.test(u.pathname)||u.pathname==='/watch/'&&u.searchParams.has('v')||u.pathname==='/watch'&&u.searchParams.has('v'))return {source:'facebook',url:value};}}catch{}return null;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,3500);}
function message(text,kind='error',withSettings=false){const el=$('#form-message');el.className='form-message'+(kind==='info'?' info':'');el.textContent=text;el.hidden=false;if(withSettings){const b=document.createElement('button');b.type='button';b.textContent='เชื่อมต่อเซิร์ฟเวอร์';b.onclick=openSettings;el.append(b);}}
function persist(){try{localStorage.setItem('clipkeep-history',JSON.stringify(records.slice(0,30)));}catch{toast('เบราว์เซอร์ไม่อนุญาตให้บันทึกประวัติ');}renderHistory();}
function addHistory(item){records=records.filter(r=>r.url!==item.url);records.unshift({...item,id:crypto.randomUUID(),date:Date.now()});records=records.slice(0,30);persist();}
function thumb(item){if(item.source==='demo')return DEMO.thumbnail;if(item.source==='youtube'){const p=parseLink(item.url);return p?`https://i.ytimg.com/vi/${p.id}/hqdefault.jpg`:'';}return '';}
function renderHistory(){$('#history-count').textContent=records.length;$('#clear-history').hidden=!records.length;$('#history-list').innerHTML=records.length?`<div class="history-grid">${records.map(r=>`<article class="history-card"><div class="history-image">${thumb(r)?`<img src="${esc(thumb(r))}" alt="" loading="lazy">`:''}<span class="type-badge">${esc(r.source==='demo'?'DEMO':r.source==='youtube'?'YouTube':'Facebook')} · ${esc((r.format||'mp4').toUpperCase())}</span></div><div class="history-content"><h3>${esc(r.title)}</h3><p>${esc(new Date(r.date).toLocaleDateString('th-TH',{day:'numeric',month:'short'}))} · ${esc(r.quality||'คุณภาพต้นฉบับ')}</p><div class="history-actions"><button data-retry="${esc(r.id)}">ดาวน์โหลดอีกครั้ง ${icon('down')}</button><button data-remove="${esc(r.id)}" aria-label="ลบ ${esc(r.title)}">${icon('close')}</button></div></div></article>`).join('')}</div>`:`<div class="empty-history"><span class="empty-icon">${icon('folder')}</span><div><h3>คลิปโปรดของคุณจะอยู่ตรงนี้</h3><p>เริ่มดาวน์โหลดคลิปแรก แล้วกลับมาหาได้ทุกเมื่อ</p></div><a href="#downloader">เริ่มเก็บคลิป ${icon('arrow')}</a></div>`;}
function resetFormat(value){if(format!==value)$('#result').hidden=true;format=value;renderSaveGuide(value);document.querySelectorAll('.format').forEach(b=>b.classList.toggle('selected',b.dataset.format===format));$('#quality').disabled=format==='mp3';}
function updateDetected(){const p=parseLink($('#video-url').value.trim());$('#detected').textContent=p?(p.source==='youtube'?'YouTube detected':'Facebook detected'):'';$('#form-message').hidden=true;}
document.querySelectorAll('.tab').forEach(btn=>btn.onclick=()=>{platform=btn.dataset.platform;document.querySelectorAll('.tab').forEach(b=>{b.classList.toggle('selected',b===btn);b.setAttribute('aria-selected',b===btn?'true':'false');});$('#video-url').placeholder=platform==='youtube'?'วางลิงก์ YouTube หรือ Shorts ที่นี่...':platform==='facebook'?'วางลิงก์ Facebook หรือ Reels ที่นี่...':'วางลิงก์ YouTube หรือ Facebook ที่นี่...';updateDetected();});
document.querySelectorAll('.format').forEach(b=>b.onclick=()=>resetFormat(b.dataset.format));$('#video-url').addEventListener('input',updateDetected);
$('#paste-btn').onclick=async()=>{try{$('#video-url').value=(await navigator.clipboard.readText()).trim();updateDetected();$('#video-url').focus();}catch{toast('แตะช่องลิงก์ แล้วใช้คำสั่งวาง หรือ Ctrl+V');$('#video-url').focus();}};
function setBusy(v){busy=v;$('#download-btn').disabled=v;$('#demo-btn').disabled=v;$('#download-btn').innerHTML=v?`${icon('clock','spinning')}<span>กำลังเตรียมไฟล์</span>`:`${icon('down')}<span>ดาวน์โหลดคลิป</span>`;}
async function api(path,options={},base=apiBase,key=apiKey){const r=await fetch((base||'')+path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(key&&path!=='/api/health'&&!path.startsWith('/api/public/')?{'Authorization':`Bearer ${key}`}:{})},signal:AbortSignal.timeout(path==='/api/health'?90000:25000)});let data;try{data=await r.json();}catch{throw Error('เซิร์ฟเวอร์ไม่ตอบกลับในรูปแบบที่รองรับ กรุณาตรวจสอบ URL');}if(!r.ok)throw Object.assign(Error(data.detail||'ติดต่อเซิร์ฟเวอร์ไม่สำเร็จ'),{status:r.status});return data;}
let pendingBackendProbe=null,pendingBackendBase='';
function backendStatus(text,state){$('#backend-status').textContent=text;$('#backend-ready').className='ready-tag '+state;}
async function checkBackend(){
  if(pendingBackendProbe&&pendingBackendBase===apiBase)return pendingBackendProbe;
  const base=apiBase;
  backendStatus('กำลังเตรียมระบบ','warming');
  const probe=api('/api/health').then(h=>{
    if(h.service!=='clipkeep')throw Error('URL นี้ไม่ใช่เซิร์ฟเวอร์สำหรับ KlipNivo');
    if(apiBase===base)backendStatus('พร้อมดาวน์โหลด','ready');
    return h;
  }).catch(error=>{
    if(apiBase===base)backendStatus('เชื่อมต่ออีกครั้งเมื่อดาวน์โหลด','retry');
    throw error;
  });
  pendingBackendProbe=probe;pendingBackendBase=base;
  try{return await probe;}finally{if(pendingBackendProbe===probe)pendingBackendProbe=null;}
}
function warmBackend(){return checkBackend().catch(()=>null);}
document.addEventListener?.('DOMContentLoaded',warmBackend,{once:true});
function showResult(item,downloadURL){renderSaveGuide(item.format);const result=$('#result');result.hidden=false;result.innerHTML=`<div class="result-card">${thumb(item)?`<img class="result-thumb" src="${esc(thumb(item))}" alt="ภาพตัวอย่างคลิป">`:''}<div class="result-info"><span class="result-badge">${item.source==='demo'?'DEMO · ไฟล์ตัวอย่าง CC0':'พร้อมบันทึก'}</span><h3>${esc(item.title)}</h3><p>${esc(item.format.toUpperCase())} · ${esc(item.quality)}${item.duration?` · ${Math.floor(item.duration/60)}:${String(Math.floor(item.duration%60)).padStart(2,'0')} นาที`:''}</p></div><button class="primary-btn" id="save-file">${icon('down')}บันทึกไฟล์</button></div>`;$('#save-file').onclick=async()=>{if(item.source==='demo'){const b=$('#save-file');b.disabled=true;b.textContent='กำลังบันทึก...';try{const r=await fetch(downloadURL);if(!r.ok)throw Error();const blob=await r.blob();const u=URL.createObjectURL(blob);saveAnchor(u,'klipnivo-demo.mp4');setTimeout(()=>URL.revokeObjectURL(u),10000);addHistory(item);toast('ส่งไฟล์ตัวอย่างไปยังรายการดาวน์โหลดแล้ว');}catch{message('โหลดไฟล์ตัวอย่างไม่สำเร็จ กรุณาลองอีกครั้ง');}finally{b.disabled=false;b.innerHTML=`${icon('down')}บันทึกไฟล์`;}}else{saveAnchor(downloadURL);addHistory(item);toast('ส่งคำขอบันทึกไฟล์แล้ว ตรวจสอบรายการดาวน์โหลดของเบราว์เซอร์');}};}
function saveAnchor(url,name){const a=document.createElement('a');a.href=url;if(name)a.download=name;a.rel='noopener';document.body.append(a);a.click();a.remove();}
$('#demo-btn').onclick=()=>{$('#form-message').hidden=true;showResult({...DEMO},DEMO.url);toast('นี่คือไฟล์ตัวอย่าง CC0 ไม่ใช่คลิปจาก Facebook หรือ YouTube');};
async function download(event){event?.preventDefault();if(busy)return;const raw=$('#video-url').value.trim();const p=parseLink(raw);$('#result').hidden=true;if(!p){message('กรุณาวางลิงก์วิดีโอ YouTube หรือ Facebook ที่ถูกต้อง');$('#video-url').focus();return;}if(platform!=='all'&&p.source!==platform){message(`ลิงก์นี้เป็น ${p.source==='youtube'?'YouTube':'Facebook'} กรุณาเปลี่ยนแท็บให้ตรงกับลิงก์ หรือเลือก “ทุกแพลตฟอร์ม”`);return;}
setBusy(true);try{let backend;message('กำลังเชื่อมต่อเซิร์ฟเวอร์… หากพักอยู่อาจใช้เวลาประมาณหนึ่งนาที','info');try{backend=await checkBackend();}catch{message('ระบบดาวน์โหลดยังไม่พร้อม กรุณารอสักครู่แล้วกดดาวน์โหลดอีกครั้ง','info');return;}if(!backend.public_downloads&&!apiKey){requestConnection('กรุณาใส่ API Key จาก Render เพื่อเชื่อมต่อเซิร์ฟเวอร์');return;}const jobsPath=backend.public_downloads?'/api/public/jobs':'/api/jobs';message('กำลังดึงวิดีโอและเตรียมไฟล์ โปรดเปิดหน้านี้ไว้…','info');const selection={url:p.url,format,quality:$('#quality').value};const {id}=await api(jobsPath,{method:'POST',body:JSON.stringify(selection)});let job;for(let i=0;i<450;i++){await new Promise(r=>setTimeout(r,2000));job=await api(`${jobsPath}/${encodeURIComponent(id)}`);if(job.status==='error')throw Error(job.error||'ไม่สามารถดาวน์โหลดคลิปนี้ได้');if(job.status==='ready')break;message(job.status==='processing'?'กำลังจัดเตรียมไฟล์วิดีโอ…':'รอคิวเตรียมไฟล์…','info');}if(job.status!=='ready')throw Error('การเตรียมไฟล์ใช้เวลานาน กรุณาลองใหม่อีกครั้ง');const file=new URL(job.download_url,apiBase||location.origin);if(file.origin!==new URL(apiBase||location.origin).origin)throw Error('เซิร์ฟเวอร์ส่งลิงก์ดาวน์โหลดที่ไม่ถูกต้อง');$('#form-message').hidden=true;showResult({title:job.title||'วิดีโอของคุณ',source:p.source,url:p.url,format:selection.format,quality:selection.format==='mp3'?'เสียงต้นฉบับ':job.height?`${job.height}p`:'คุณภาพต้นฉบับ',duration:job.duration},file.href);}catch(e){if(e.status===401){requestConnection('API Key ไม่ถูกต้อง กรุณาคัดลอกค่า CLIPKEEP_API_KEY จาก Render มาใส่อีกครั้ง');}else message(e.name==='TimeoutError'?'เซิร์ฟเวอร์ใช้เวลาตอบกลับนาน กรุณาลองอีกครั้ง':e.message||'เกิดข้อผิดพลาด กรุณาลองอีกครั้ง');}finally{setBusy(false);}}
$('#download-form').addEventListener('submit',download);
function openSettings(){$('#api-url').value=apiBase;$('#api-key').value=apiKey;$('#remember-key').checked=rememberKey;$('#settings-message').hidden=true;if(!$('#settings-dialog').open)$('#settings-dialog').showModal();}
function requestConnection(text){message(text,'info',true);openSettings();$('#settings-message').textContent=text;$('#settings-message').hidden=false;$('#api-key').focus();}
$('#forget-key').onclick=()=>{apiKey='';rememberKey=false;for(const name of ['localStorage','sessionStorage']){try{globalThis[name].removeItem('clipkeep-connection');}catch{}}$('#api-key').value='';$('#remember-key').checked=false;$('#api-key').focus();toast('ลบคีย์ที่บันทึกบนอุปกรณ์นี้แล้ว');};
$('#settings-btn').onclick=openSettings;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());
$('#settings-form').onsubmit=async(e)=>{e.preventDefault();const input=$('#api-url').value.trim().replace(/\/+$/,'');const error=$('#settings-message');try{if(input){const u=new URL(input);if(!['https:','http:'].includes(u.protocol)||u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error('กรุณาใส่ URL เซิร์ฟเวอร์ เช่น https://your-server.example.com');if(location.protocol==='https:'&&u.protocol!=='https:')throw Error('เว็บนี้ต้องเชื่อมต่อเซิร์ฟเวอร์ผ่าน HTTPS');}const oldBase=apiBase,oldKey=apiKey;apiBase=input;apiKey=$('#api-key').value.trim();try{const backend=await checkBackend();if(apiKey)await api('/api/auth-check');else if(!backend.public_downloads)throw Error('กรุณาใส่ API Key จาก Render');}catch(e){apiBase=oldBase;apiKey=oldKey;throw e;}try{localStorage.setItem('clipkeep-api',apiBase);}catch{}const remembered=saveConnectionKey($('#remember-key').checked);$('#settings-dialog').close();toast(remembered?'เชื่อมต่อเซิร์ฟเวอร์เรียบร้อยแล้ว':'เชื่อมต่อแล้ว แต่เบราว์เซอร์ไม่อนุญาตให้จำคีย์บนอุปกรณ์นี้');}catch(e){error.textContent=e.message||'เชื่อมต่อไม่สำเร็จ';error.hidden=false;}};
$('#clear-history').onclick=()=>$('#confirm-dialog').showModal();$('#confirm-clear').onclick=()=>{records=[];persist();$('#confirm-dialog').close();toast('ล้างประวัติแล้ว');};$('#history-list').onclick=(e)=>{const remove=e.target.closest('[data-remove]');if(remove){records=records.filter(r=>r.id!==remove.dataset.remove);persist();return;}const retry=e.target.closest('[data-retry]');if(retry){const r=records.find(r=>r.id===retry.dataset.retry);if(!r)return;$('#downloader').scrollIntoView({behavior:'smooth'});if(r.source==='demo'){$('#demo-btn').click();return;}$('#video-url').value=r.url;document.querySelector('[data-platform="all"]').click();resetFormat(r.format||'mp4');updateDetected();download();}};
$('#year').textContent=new Date().getFullYear();renderHistory();

const DEVICE_GUIDES = {
  iphone: {name:'iPhone', steps:['เมื่อไฟล์พร้อม แตะ “บันทึกไฟล์” ด้านบน แล้วเลือกดาวน์โหลด หากมีหน้าต่างถาม','เปิดแอป “ไฟล์” แล้วเข้าโฟลเดอร์ “ดาวน์โหลด” เพื่อหาไฟล์ของคุณ','เปิดไฟล์เพื่อดู ฟัง หรือแตะแชร์เพื่อส่งต่อ'], mobile:true},
  android: {name:'Android', steps:['เมื่อไฟล์พร้อม แตะ “บันทึกไฟล์” ด้านบน แล้วอนุญาตการดาวน์โหลดหากเบราว์เซอร์ถาม','เปิดเมนู “ดาวน์โหลด” ใน Chrome หรือโฟลเดอร์ Downloads ในแอปไฟล์','แตะไฟล์ที่ดาวน์โหลดเพื่อเปิดดูหรือฟังบนเครื่องของคุณ']},
  ipad: {name:'iPad', steps:['เมื่อไฟล์พร้อม แตะ “บันทึกไฟล์” ด้านบน แล้วเลือกดาวน์โหลด หากมีหน้าต่างถาม','เปิดแอป “ไฟล์” แล้วหาโฟลเดอร์ “ดาวน์โหลด” หรือแตะรายการดาวน์โหลดใน Safari','เปิดไฟล์เพื่อดู ฟัง หรือแตะแชร์เพื่อส่งต่อ'], mobile:true},
  laptop: {name:'โน้ตบุ๊ก', steps:['เมื่อไฟล์พร้อม คลิก “บันทึกไฟล์” ด้านบน เพื่อเริ่มดาวน์โหลด','ถ้ามีหน้าต่างถามตำแหน่ง ให้เลือกโฟลเดอร์แล้วกด Save หรือบันทึก','หาไฟล์ในโฟลเดอร์ Downloads หรือรายการดาวน์โหลดของเบราว์เซอร์ ใช้ได้ทั้ง Windows และ Mac']},
  desktop: {name:'คอมพิวเตอร์', steps:['เมื่อไฟล์พร้อม คลิก “บันทึกไฟล์” ด้านบน เพื่อเริ่มดาวน์โหลด','ถ้ามีหน้าต่างถามตำแหน่ง ให้เลือกโฟลเดอร์แล้วกด Save หรือบันทึก','เปิดโฟลเดอร์ Downloads หรือรายการดาวน์โหลดของเบราว์เซอร์ แล้วเปิดไฟล์ที่บันทึกไว้']}
};
function detectSaveDevice(){const n=globalThis.navigator||{};const ua=n.userAgent||'';if(/iPad/i.test(ua)||n.platform==='MacIntel'&&n.maxTouchPoints>1)return 'ipad';if(/iPhone|iPod/i.test(ua))return 'iphone';if(/Android/i.test(ua))return 'android';return 'desktop';}
let selectedDevice=detectSaveDevice(),guideFormat='mp4';
try{const saved=localStorage.getItem('klipnivo-device');if(Object.hasOwn(DEVICE_GUIDES,saved))selectedDevice=saved;}catch{}
function renderSaveGuide(value=guideFormat){
  guideFormat=value;
  const guide=DEVICE_GUIDES[selectedDevice];
  $('#guide-title').textContent='วิธีบันทึก'+(value==='mp3'?'เสียง MP3':'วิดีโอ MP4')+' บน'+guide.name;
  $('#guide-steps').innerHTML=guide.steps.map(step=>'<li>'+esc(step)+'</li>').join('');
  $('#guide-file-note').textContent=value==='mp3'?'ไฟล์ MP3 เป็นไฟล์เสียง เปิดฟังได้จากแอปไฟล์หรือแอปเล่นเพลง':guide.mobile?'หากมีตัวเลือก “บันทึกวิดีโอ” ให้เปิดไฟล์ → แชร์ → บันทึกวิดีโอ เพื่อเก็บในแอปรูปภาพ':'ไฟล์ MP4 เปิดดูได้ด้วยแอปวิดีโอที่รองรับบนอุปกรณ์ของคุณ';
  document.querySelectorAll('[data-device]').forEach(button=>button.setAttribute('aria-pressed',button.dataset.device===selectedDevice?'true':'false'));
}
document.querySelectorAll('[data-device]').forEach(button=>button.onclick=()=>{
  selectedDevice=button.dataset.device;
  try{localStorage.setItem('klipnivo-device',selectedDevice);}catch{}
  renderSaveGuide();
});
function updateLiveClock(){const now=new Date();$('#local-clock').textContent=now.toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});$('#local-clock').dateTime=now.toISOString();}
renderSaveGuide();
updateLiveClock();
globalThis.setInterval?.(updateLiveClock,1000);
